#include <stdio.h>
typedef struct Axis6W7bRow { unsigned int lane, watermark, shadow; int delta; } Axis6W7bRow;
typedef struct Axis6W7bAgg { unsigned int watermark[4], shadow[4]; int value[4]; } Axis6W7bAgg;
static unsigned int mix7b(unsigned int h,unsigned int v){ h ^= v + 0x9e3779b9u + (h<<6) + (h>>2); return h; }
static void clear7b(Axis6W7bAgg* a){ for(int i=0;i<4;++i){ a->watermark[i]=0u; a->shadow[i]=0u; a->value[i]=0; } }
static void absorb7b(Axis6W7bAgg* a,const Axis6W7bRow* r){ unsigned int lane=r->lane%4u; if(r->watermark<a->watermark[lane]) return; if(r->watermark>a->watermark[lane]){ a->watermark[lane]=r->watermark; a->shadow[lane]=r->shadow; a->value[lane]=r->delta; return; } if(r->shadow>a->shadow[lane]){ a->shadow[lane]=r->shadow; a->value[lane]=r->delta; } else if(r->shadow==a->shadow[lane]) a->value[lane]+=r->delta; }
static unsigned int sig7b(const Axis6W7bAgg* a){ unsigned int h=2166136261u; for(unsigned int lane=0; lane<4u; ++lane){ h=mix7b(h,lane+1u); h=mix7b(h,a->watermark[lane]); h=mix7b(h,a->shadow[lane]); h=mix7b(h,(unsigned int)(a->value[lane]&0xffff)); } return h; }
int main(void){ const Axis6W7bRow rows[]={{0u,2u,1u,5},{1u,3u,2u,4},{2u,1u,3u,6},{3u,2u,4u,7},{0u,4u,2u,3},{1u,5u,1u,8},{2u,4u,5u,2},{3u,5u,3u,9},{0u,4u,2u,-1},{1u,5u,4u,1},{2u,4u,5u,-2},{3u,5u,3u,-4},{0u,6u,3u,7},{1u,6u,4u,6},{2u,6u,6u,5},{3u,6u,5u,4}}; Axis6W7bAgg d,g; clear7b(&d); for(unsigned int i=0;i<sizeof(rows)/sizeof(rows[0]);++i) absorb7b(&d,&rows[i]); clear7b(&g); for(unsigned int watermark=1u; watermark<=6u; ++watermark) for(unsigned int shadow=1u; shadow<=6u; ++shadow) for(unsigned int lane=0; lane<4u; ++lane){ int merged=0,saw=0; for(unsigned int i=0;i<sizeof(rows)/sizeof(rows[0]);++i){ if(rows[i].lane%4u!=lane || rows[i].watermark!=watermark || rows[i].shadow!=shadow) continue; merged+=rows[i].delta; saw=1; } if(saw){ Axis6W7bRow row={lane,watermark,shadow,merged}; absorb7b(&g,&row); } } { unsigned int sd=sig7b(&d), sg=sig7b(&g); printf("%u %u %u\n", sd, sg, (sd==sg)?1u:0u); } return 0; }
